"""Local normal-speed review of new trimmed cuts. Reuse the existing range server."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[4];P=Path(__file__).resolve().parent
plan=json.loads((P/'chicory-trimmed-framing-plan-v2.json').read_text(encoding='utf-8'))
out=ROOT/'shared/assets/presenting-game-scores/raw/limited-chicory-trimmed-framing-v2.html';assert not out.exists()
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><title>Chicory trimmed framing review v2</title>
<style>@font-face{font-family:NotoLocal;src:local('Noto Sans KR');font-weight:100 900}body{margin:16px;background:#181818;color:white;font:16px sans-serif}button,select{font:inherit;margin:5px;padding:7px}canvas{display:block;width:min(1920px,100%);aspect-ratio:16/9;background:black}video{display:none}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style>
<label for="cut">수정 컷</label><select id="cut"></select><button id="prepare">준비</button><button id="play">정상속도 재생</button><button id="pause">일시정지</button><label><input type="checkbox" id="overlay" checked>실제 규격 자막 시험</label><span id="status">준비 전</span>
<canvas id="canvas" width="1920" height="1080"></canvas><video id="video" muted playsinline preload="metadata"></video>
<p>정상속도1×·음소거·같은 원본 프레임을 크롭/밑부분 블러에 사용합니다. 자막은 시험 문구입니다. 모든 연속 프레임·최종 내레이션 큐·권리 승인과 구별합니다. 정확 인아웃은 원본 native PTS만 따릅니다.</p><pre id="state"></pre><pre id="events"></pre>
<script>const cuts=__CUTS__,v=document.getElementById('video'),sel=document.getElementById('cut'),can=document.getElementById('canvas'),ctx=can.getContext('2d'),status=document.getElementById('status'),state=document.getElementById('state'),ev=document.getElementById('events');let current=null,events=[],mediaTime=null,active=false,callback=null;
cuts.forEach(c=>{let o=document.createElement('option');o.value=c.key;o.textContent=c.key+' / '+c.sourceStartSeconds+'–'+c.sourceEndSecondsExclusive+' / up'+c.framingUpPixels;sel.append(o)});
function draw(){if(!current||v.readyState<2)return;ctx.save();ctx.clearRect(0,0,1920,1080);const up=current.framingUpPixels;if(up){ctx.drawImage(v,0,up,1920,1080-up,0,0,1920,1080-up);ctx.save();ctx.beginPath();ctx.rect(0,1080-up,1920,up);ctx.clip();ctx.filter='blur(22px)';ctx.drawImage(v,0,1080-up,1920,up,0,1080-up,1920,up);ctx.restore()}else ctx.drawImage(v,0,0,1920,1080);if(document.getElementById('overlay').checked){ctx.font='500 48px NotoLocal,"Noto Sans KR",sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';let lines=['색이 바뀌어도 윤곽과 높이로','길의 상태를 읽을 수 있습니다.'],bw=Math.round(Math.max(...lines.map(s=>ctx.measureText(s).width)))+44,bh=146,x=960-bw/2,y=897;ctx.fillStyle='#073c32';ctx.fillRect(x+14,y+14,bw,bh);ctx.fillStyle='white';ctx.fillRect(x,y,bw,bh);ctx.strokeStyle='#161b18';ctx.lineWidth=3;ctx.strokeRect(x+1.5,y+1.5,bw-3,bh-3);ctx.fillStyle='#080b09';lines.forEach((s,i)=>ctx.fillText(s,960,y+11+(i+.5)*62))}ctx.restore()}
function show(){state.textContent=JSON.stringify(current?{key:current.key,startFrame:current.startFrame,endFrameExclusive:current.endFrameExclusive,exactStartPts:current.startPts,exactEndPtsExclusive:current.endPtsExclusive,timebase:current.timeBase,start:current.sourceStartSeconds,end:current.sourceEndSecondsExclusive,framingUp:current.framingUpPixels,current:v.currentTime,mediaTime,paused:v.paused,muted:v.muted,rate:v.playbackRate,fontAvailable:document.fonts.check('500 48px NotoLocal'),captionTestOnly:true}:{});ev.textContent=JSON.stringify(events)}
function log(kind){events.push({kind,key:current.key,at:new Date().toISOString(),current:v.currentTime,mediaTime,muted:v.muted,rate:v.playbackRate,paused:v.paused,framingUp:current.framingUpPixels});show()}
function frame(now,meta){mediaTime=meta.mediaTime;draw();if(active&&v.currentTime>=current.sourceEndSecondsExclusive){active=false;v.pause();status.textContent='수정 컷 재생 완료';log('end')}else if(active)callback=v.requestVideoFrameCallback(frame);show()}
document.getElementById('prepare').onclick=async()=>{active=false;v.pause();if(callback!==null)v.cancelVideoFrameCallback(callback);current=cuts.find(c=>c.key===sel.value);mediaTime=null;v.muted=true;v.playbackRate=1;await document.fonts.load('500 48px NotoLocal');if(!v.currentSrc.endsWith(current.sourceFile)){v.src=current.sourceFile;await new Promise(r=>v.addEventListener('loadedmetadata',r,{once:true}))}v.currentTime=current.sourceStartSeconds;await new Promise(r=>v.addEventListener('seeked',r,{once:true}));draw();status.textContent='수정 컷 준비';log('prepared');v.requestVideoFrameCallback((now,meta)=>{mediaTime=meta.mediaTime;draw();show()})};
document.getElementById('play').onclick=async()=>{if(!current)return;active=true;v.muted=true;v.playbackRate=1;callback=v.requestVideoFrameCallback(frame);await v.play();status.textContent='수정 컷 정상속도 재생 중';log('start')};document.getElementById('pause').onclick=()=>{active=false;v.pause();draw();status.textContent='일시정지';if(current)log('pause')};document.getElementById('overlay').onchange=()=>{draw();show()};show();</script></html>'''
out.write_text(page.replace('__CUTS__',json.dumps(plan['cuts'],ensure_ascii=False)),encoding='utf-8')
print(json.dumps({'helper':str(out),'cuts':len(plan['cuts']),'seconds':plan['uniqueAvailableSeconds'],'newServer':False,'mediaEncode':False},ensure_ascii=False))
